class FakeHttpClient:
    """Simulates an HTTP client's behavior without any real network call."""
    def get(self, path, headers=None, timeout=5):
        headers = headers or {}
        if path == '/secure' and headers.get('Authorization') != 'Bearer valid-token':
            return {'status_code': 401, 'body': {'error': 'unauthorized'}}
        return {'status_code': 200, 'body': {'data': 'ok'}}

client = FakeHttpClient()

resp = client.get('/secure')
print(f"no token: {resp['status_code']}")

resp = client.get('/secure', headers={'Authorization': 'Bearer valid-token'})
print(f"valid token: {resp['status_code']}")
